def count_grey_cells(R, C, K):
    def is_white_cell(r, c):
        return bin(r).count('1') > 0 or bin(c).count('1') > 0

    def count_white_cells_up_to(r, c):
        count = 0
        for i in range(r + 1):
            for j in range(c + 1):
                if is_white_cell(i, j):
                    count += 1
        return count

    def find_position(K):
        low, high = 0, min(R, C)
        while low < high:
            mid = (low + high + 1) // 2
            if count_white_cells_up_to(mid - 1, mid - 1) < K:
                low = mid
            else:
                high = mid - 1
        return low

    def count_grey_in_row(r, K):
        count = 0
        for c in range(C):
            if not is_white_cell(r, c):
                count += 1
        return count

    row = find_position(K)
    K -= count_white_cells_up_to(row - 1, C - 1)
    grey_count = count_grey_in_row(row, K)

    return grey_count

